// Stage 8: the demo kernel rig -- stages 2 through 6 together, no phone.
//
// This is the test the roadmap calls "the desktop test rig that proves
// stages 2-6 together": the bundled self-test kernel (app/src/main/assets/
// demo-kernel.img3, generated by scripts/gen_demo_kernel.py with keystone)
// goes through the real loader (IMG3 -> comp/LZSS -> Mach-O -> segments),
// runs on the real interpreter against the real storage-backed image,
// paints the real VRAM through the real guest map, presents frames through
// the stage-5 renderer into a recording backend, and powers off with the
// engine's clean SVC. Every effect it leaves in guest memory is checked.
//
// Run: tests/run_desktop_tests.sh   (or link manually with the host g++)

#include <sys/stat.h>
#include <unistd.h>

#include <cstdio>
#include <string>
#include <vector>

#include "hakios/emulator.h"
#include "hakios/guest_map.h"

using hakios::Arm7Cpu;
using hakios::Emulator;

static int g_failures = 0;

#define CHECK(cond)                                                        \
    do {                                                                   \
        if (!(cond)) {                                                     \
            std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);   \
            ++g_failures;                                                   \
        }                                                                   \
    } while (0)

// the constants the kernel and this rig agree on (scripts/gen_demo_kernel.py)
namespace agreed {
constexpr uint64_t kVram      = 0x20000000;
constexpr uint32_t kScreenW   = 640;
constexpr uint32_t kScreenH   = 960;
constexpr uint64_t kTestArea  = 0x80040000;
constexpr size_t   kTestWords = 64 * 1024 / 4;
constexpr uint32_t kPattern   = 0x600DF00D;
constexpr uint32_t kMarker    = 0x3A1D5C5E;
constexpr uint32_t kExpectedPixel(uint32_t y) {
    return 0x801Fu | ((y & 0x3Fu) << 5);
}
}  // namespace agreed

namespace {

class RecordingBackend : public hakios::FrameRenderer::Backend {
public:
    bool init(int* w, int* h, std::string*) override {
        *w = 1080;
        *h = 2340;
        return true;
    }
    void upload_rgb565(const uint16_t* pixels, int w, int h) override {
        if (uploads == 0) {                 // keep the first frame for checks
            first.assign(pixels, pixels + size_t(w) * h);
            fw = w;
            fh = h;
        }
        uploads++;
    }
    void draw_quad(float, float, float, float) override { quads++; }
    void swap() override { swaps++; }
    int uploads = 0, swaps = 0, quads = 0, fw = 0, fh = 0;
    std::vector<uint16_t> first;
};

std::string test_file(const char* name) {
    static std::string dir;
    if (dir.empty()) {
        char tmpl[] = "/tmp/hakios-demo-test-XXXXXX";
        if (!::mkdtemp(tmpl)) {
            std::printf("FAIL: mkdtemp\n");
            std::exit(1);
        }
        dir = tmpl;
    }
    return dir + "/" + name;
}

std::vector<uint8_t> read_file(const char* path) {
    std::FILE* f = std::fopen(path, "rb");
    if (!f) return {};
    std::fseek(f, 0, SEEK_END);
    const long size = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    std::vector<uint8_t> out(size);
    size_t have = 0;
    while (have < size_t(size)) {
        const size_t n = std::fread(out.data() + have, 1, size - have, f);
        if (n == 0) break;
        have += n;
    }
    std::fclose(f);
    out.resize(have);
    return out;
}

}  // namespace

static void test_demo_kernel_end_to_end() {
    std::vector<uint8_t> kernel = read_file("app/src/main/assets/demo-kernel.img3");
    CHECK(!kernel.empty());      // run from the repository root (the rig does)

    Emulator e;
    std::string err;
    CHECK(e.create(test_file("demo-guest.img"), &err));
    CHECK(e.load_kernel(kernel.data(), kernel.size(), nullptr, nullptr, &err));
    if (!err.empty()) std::printf("load: %s\n", err.c_str());
    // the loader recognized the whole chain: IMG3, comp/LZSS, Mach-O
    CHECK(e.entry_pc() == 0x80001000);

    RecordingBackend display;
    e.set_display(&display);

    // enough steps to fill+verify 64 KiB, paint 614,400 pixels, and reach
    // the SVC: the kernel retires roughly 4 million instructions
    const uint64_t ran = e.run_sync(20 * 1000 * 1000);
    CHECK(ran > 100 * 1000);

    const Emulator::Status s = e.status();
    CHECK(s.state == Emulator::State::kHalted);
    CHECK(s.halt.reason == Arm7Cpu::Halt::kSupervisorCall);
    CHECK(s.halt.clean_poweroff);            // SVC #0x0FF, on purpose
    CHECK(s.halt.insn == 0xEF0000FFu);

    // 1. the memory test came back clean
    CHECK(e.memory().read32(agreed::kVram) == agreed::kMarker);
    CHECK(e.memory().read32(agreed::kVram + 4) == 0);   // zero errors
    // the pattern really is in the test area (fill and verify both ran)
    CHECK(e.memory().read32(agreed::kTestArea) == agreed::kPattern);
    CHECK(e.memory().read32(agreed::kTestArea + 4 * (agreed::kTestWords - 1)) ==
          agreed::kPattern);

    // 2. the framebuffer holds the agreed image: the marker sits over the
    //    first two pixels by design (VRAM+0/+4), so the paint formula is
    //    checked from the third pixel on -- corners, edges, center
    auto pixel = [&](uint32_t x, uint32_t y) {
        return e.memory().read16(agreed::kVram +
                                 2 * (size_t(y) * agreed::kScreenW + x));
    };
    CHECK(pixel(0, 0) == (agreed::kMarker & 0xFFFF));         // the marker
    CHECK(pixel(1, 0) == (agreed::kMarker >> 16));
    CHECK(pixel(2, 0) == 0);                                   // error count
    CHECK(pixel(3, 0) == 0);
    CHECK(pixel(4, 0) == agreed::kExpectedPixel(0));           // row 0 resumes
    CHECK(pixel(agreed::kScreenW - 1, 0) == agreed::kExpectedPixel(0));
    CHECK(pixel(0, agreed::kScreenH - 1) == agreed::kExpectedPixel(agreed::kScreenH - 1));
    CHECK(pixel(agreed::kScreenW - 1, agreed::kScreenH - 1) ==
          agreed::kExpectedPixel(agreed::kScreenH - 1));
    CHECK(pixel(agreed::kScreenW / 2, agreed::kScreenH / 2) ==
          agreed::kExpectedPixel(agreed::kScreenH / 2));
    CHECK(pixel(3, 63) == agreed::kExpectedPixel(63));
    CHECK(pixel(600, 500) == agreed::kExpectedPixel(500));

    // 3. frames went out through the stage-5 path, and the first one is the
    //    guest's own bytes (the renderer's upload, byte for byte)
    CHECK(display.uploads >= 1);
    CHECK(display.swaps == display.uploads);
    CHECK(display.fw == int(agreed::kScreenW) && display.fh == int(agreed::kScreenH));
    CHECK(display.first.size() == agreed::kScreenW * agreed::kScreenH);
    CHECK(display.first[0] == (agreed::kMarker & 0xFFFF));    // final state:
    CHECK(display.first[1] == (agreed::kMarker >> 16));       // marker and
    CHECK(display.first[2] == 0);                              // error count
    CHECK(display.first[4] == agreed::kExpectedPixel(0));      // sit on row 0
    CHECK(display.first[agreed::kScreenW * agreed::kScreenH - 1] ==
          agreed::kExpectedPixel(agreed::kScreenH - 1));

    // 4. "installed stays installed": the same image re-opens, the same
    //    kernel re-loads, and it boots again
    e.pause();
    e.close();
    Emulator again;
    CHECK(again.open(test_file("demo-guest.img"), &err));
    CHECK(again.load_kernel(kernel.data(), kernel.size(), nullptr, nullptr, &err));
    CHECK(again.run_sync(20 * 1000 * 1000) > 100 * 1000);
    CHECK(again.status().halt.clean_poweroff);
    CHECK(again.memory().read32(agreed::kVram) == agreed::kMarker);
}

int main() {
    test_demo_kernel_end_to_end();
    if (g_failures == 0)
        std::printf("demo kernel tests: OK (load, run, memory test, framebuffer, "
                    "power-off, persistence)\n");
    else
        std::printf("demo kernel tests: %d failure(s)\n", g_failures);
    return g_failures ? 1 : 0;
}
